Plan: read the cached values from the active sheet, then for each Q2:Q6 row compute the average of B3:L8 cells whose column size in row 2 matches P and whose row rating in M matches S2. Write numeric averages where matches exist, otherwise leave the cell empty.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

vws = vals.active
answer_sheet_name = vws.title
if answer_sheet_name not in wb.sheetnames:
    ws = wb.create_sheet(answer_sheet_name)
else:
    ws = wb[answer_sheet_name]

def numeric_key(value):
    if value is None:
        return None
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return float(value)
    s = str(value).strip()
    if s == "":
        return None
    try:
        return float(s)
    except Exception:
        return s

def text_key(value):
    if value is None:
        return None
    if isinstance(value, bool):
        return str(value)
    s = str(value).strip()
    return s if s != "" else None

target_rating = text_key(vws["S2"].value)

size_cols = range(2, 13)      # B through L
data_rows = range(3, 9)       # rows 3 through 8

for q_row in range(2, 7):     # Q2:Q6
    p_value = numeric_key(vws.cell(row=q_row, column=16).value)  # column P
    matching_values = []

    if p_value is not None:
        for col in size_cols:
            size = numeric_key(vws.cell(row=2, column=col).value)
            if size is None:
                continue

            if isinstance(size, float) and isinstance(p_value, float):
                if size != p_value:
                    continue
            else:
                if size != p_value:
                    continue

            for row in data_rows:
                rating = text_key(vws.cell(row=row, column=13).value)  # column M
                if target_rating is None:
                    if rating is not None:
                        continue
                else:
                    if rating != target_rating:
                        continue

                cell_value = vws.cell(row=row, column=col).value
                if isinstance(cell_value, bool):
                    continue
                if isinstance(cell_value, (int, float)):
                    matching_values.append(float(cell_value))
                else:
                    try:
                        matching_values.append(float(str(cell_value).strip()))
                    except Exception:
                        pass

    if matching_values:
        avg = sum(matching_values) / len(matching_values)
        ws.cell(row=q_row, column=17).value = round(avg, 2)
    else:
        ws.cell(row=q_row, column=17).value = None

    print(f"Q{q_row}: P={p_value}, result={ws.cell(row=q_row, column=17).value}")

wb.save(OUT)
